import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';

import { IonicModule, IonicRouteStrategy } from '@ionic/angular';

import { ReferredStudentPageRoutingModule } from './referred-student-routing.module';

import { ReferredStudentPage } from './referred-student.page';
import { File } from '@ionic-native/file/ngx';
import { FileOpener } from '@ionic-native/file-opener/ngx';
import { RouteReuseStrategy } from '@angular/router';

@NgModule({
  imports: [
    CommonModule,
    FormsModule,
    IonicModule,
    ReferredStudentPageRoutingModule
  ],
  declarations: [ReferredStudentPage],
  providers: [
    File,
    FileOpener,
    {
      provide: RouteReuseStrategy,
      useClass: IonicRouteStrategy,
    },
  ],

})
export class ReferredStudentPageModule {}
